INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nastar', 'Rastan Saga II (ラスタンサーガ2?), known in Europe as Nastar and in North America as Nastar Warrior (except for the North American Sega Mega Drive/Genesis version, which was known as Rastan Saga II) is a hack and slash platform arcade game developed and released by Taito in 1988. It is the sequel to Rastan Saga (released simply as Rastan in North America).' FROM games WHERE igdb_id = 6818 ON CONFLICT (game_id, language_code) DO NOTHING;
