INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hikaru Genji: Roller Panic', 'Your goal in the game is to outfit all 7 band members with roller skates to make the big gig at the arena. I believe you can tackle each band member’s part in any order but if you are having problems just follow the same flow as in the walkthrough below. You can switch the characters around while in the game.' FROM games WHERE igdb_id = 41308 ON CONFLICT (game_id, language_code) DO NOTHING;
