INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Run Run Kyousoukyoku', 'Run Run Kyousoukyoku is an arcade-style on-foot racing game. It uses a split-screen side-scrolling view and can be player against computer-controlled opponents or in a two-player mode. The latter allows players to choose any stage, while the former follows a linear set of levels, starting in Tokyo and advancing to the USA via China and Europe. The courses typically feature platforming sections alongside flat terrain; it is usually required to jump in a timed fashion to succeed, and jumps can vary in height and length depending on how long the player holds the correspondent key. Runners would also take falling damage in certain spots.' FROM games WHERE igdb_id = 210821 ON CONFLICT (game_id, language_code) DO NOTHING;
