INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('billiards-simulator', 14304, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91ax.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vuuhhiqxfgxta25fqydz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Billiards Simulator', 'Billiards Simulator is a carom billiards game which is played with three balls and on a table without pockets. In the first phase of the shot, the cue is aligned to the ball. Here the player can either use the full 3D perspective or a top-down view. After that, the used cue (there are three), the spin and the strength of the shot is chosen by aligning diagrams and sliders. Then the shot is performed and points assigned. Additionally the player can set certain parameters to change the game experience, e.g. ball weight, friction or rebound.' FROM games WHERE igdb_id = 14304 ON CONFLICT (game_id, language_code) DO NOTHING;
