INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rastan Saga II', 'Rastan Saga 2 is the sequel to Rastan, containing the same hack-em''/slash-''em gameplay as the original. You are a warrior who must get through a number of levels, and trying to collect gems which can only be obtained by defeating the end-of-level bosses. Collecting power-ups along the way awards you with extra life or better weapons.' FROM games WHERE igdb_id = 4466 ON CONFLICT (game_id, language_code) DO NOTHING;
