INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Welltris', 'Welltris is a puzzle video game, developed by Doka and licensed to Bullet-Proof Software. Adaptations were made by Sphere, Inc for Spectrum Holobyte, and by Infogrames. It was originally released for DOS and Macintosh in 1989. It was subsequently ported to the Amiga and Atari ST in 1990 and the ZX Spectrum and Commodore 64 in 1991.' FROM games WHERE igdb_id = 12872 ON CONFLICT (game_id, language_code) DO NOTHING;
