INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'David Wolf: Secret Agent', 'David Wolf: Secret Agent merges digitized cinematic cutscenes with bitmap and 3D animation to create an action-based interactive movie. Four 3D action simulations are the heart of the game: HangGliding (with a machine gun mounted to the front), Sportscar driving (with a machine gun mounted to the front), Fighter Simulation (with a machine gun and a missile launcher mounted to the front), and Skydiving (no machine gun). The player follows along with the story for a few minutes, then is attacked and must outwit his opponents to live.' FROM games WHERE igdb_id = 57575 ON CONFLICT (game_id, language_code) DO NOTHING;
