INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Dutchman Mine', 'Somewhere deep in the vast and rugged Superstition Mountains of Arizona, there lies hidden a gold mine of immense richness. It was allegedly discovered by a prospector named Jacob Waltz, an old German immigrant who wandered the Superstitions during the early 1880''s. He claimed the mine was so rich that the gold could be removed with only a knife.
