INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midwinter', 'Midwinter is a post-apocalyptic first-person action role-playing game with strategy and survival elements for the Atari ST, Amiga and PC. It was designed by Mike Singleton and was released in 1989 by Microplay Software. The game was critically acclaimed and commercially successful enough to get a sequel titled Flames of Freedom in 1991. A remake (as of April 2014) is currently in development.' FROM games WHERE igdb_id = 12681 ON CONFLICT (game_id, language_code) DO NOTHING;
