INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chuck Yeager''s Advanced Flight Trainer 2.0', 'Chuck Yeager''s Advanced Flight Trainer 2.0 is a flight simulator game. Follow Yeager''s cursor, instrument settings and instructions on a couple of landings and you''ll set her down right every time. Hug the ground at 50 feet, pull 8 G''s around the pylon and streak full-throttle for home. Screaming toward earth at supersonic speed, you''re a breath away from drilling a hole. In test piloting, the real hero is the one who survives.' FROM games WHERE igdb_id = 13494 ON CONFLICT (game_id, language_code) DO NOTHING;
