INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Same! Same! Same!', 'A shooting game developed and published by Toaplan, released in 1989. The Original Japanese version of what was released in the west as Fire Shark, ''Same! Same! Same!'' is notable for being single-player only and having a dramatically heightened degree of difficulty compared to its western release, as well as lacking a number of glitches that came as a result of the conversion to a 2 player game.' FROM games WHERE igdb_id = 197817 ON CONFLICT (game_id, language_code) DO NOTHING;
