INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hokuto no Ken 3: Shinseiki Souzou Seiken Retsuden', 'Hokuto no Ken 3: Shinseiki Souzou Seiken Retsuden is the third Hokuto no Ken video game developed by Shouei Systems and released by Toei Animation for the Family Computer (the Japanese version of the Nintendo Entertainment System) on October 19, 1989. Unlike the first two Hokuto no Ken video games for the platform, which were side-scrolling action games, Hokuto no Ken 3 is a role playing game which adapts the storyline of the original manga from the beginning to the Kingdom of Shura story arc. It was the first in a trilogy of RPGs based on the franchise.' FROM games WHERE igdb_id = 48471 ON CONFLICT (game_id, language_code) DO NOTHING;
