INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('block-hole', 40029, '1989-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ie3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq4rz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Block Hole', 'Block Hole is a combination of Tetris-style gameplay and a fixed shooter in the Space Invaders tradition. The player''s focus is on falling blocks, and the action is geometrical. Rather than arranging the blocks together to make a row of disappearing blocks, a spaceship positioned at the bottom of the screen shoots blocks upwards to make the falling block pattern into squares or rectangles. Once the blocks have been arranged properly, the shape is destroyed and the player is awarded points based on the shape''s size. The blocks continue to drop from the top of the screen in various incomplete shapes. As each level progresses, the blocks drop at greater speed and frequency. There are also various power-ups which could be located to increase your ship''s speed, among other bonuses.
