INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tashiro Masashi no Princess ga Ippai', 'The story is about the hero Masashi Tashiro who has to rescue the four princesses in distress. One happy ending and four unhappy endings were used in the game; becoming one of the first video games to have multiple endings. The game was not very successful, but it started appearing frequently and getting high prices on online auction sites like Yahoo! after 2000, when Masashi Tashiro was arrested and convicted several times in connection with voyeurism and drug abuse.' FROM games WHERE igdb_id = 41709 ON CONFLICT (game_id, language_code) DO NOTHING;
