INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Paranoia Complex', 'The Paranoia Complex takes place in a city controlled by a rogue computer which has its dictatorial grasp over it. The player takes the role of a citizen who has the dirty job to hunt down terrorist rebels. This simply plays out that the computer gives instructions, the player walks to the terrorist in the top-down city and shoots him. After collecting a disk from the body and bringing it to a special terminal, money and promotions wait as reward.' FROM games WHERE igdb_id = 69494 ON CONFLICT (game_id, language_code) DO NOTHING;
