INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Ninja Brothers', 'Little Ninja Brothers, known in Japan as Super Chinese 2, is a 1989 video game developed and published by Culture Brain for the Nintendo Entertainment System in 1989 in Japan, 1990 in the United States, and 1991 in Europe. It is the second game in the Super Chinese series. The plot follows two young ninjas, Jack and Ryu, attempting to find out the mysterious reason for the invasion of Chinaland by Blu Boltar. It was the second game in the series, preceded by Kung-Fu Heroes, and followed up by a sequel Super Ninja Boy, released on the Super NES. There were also two Ninja Boy spin-off games released for the Game Boy in both regions. A manga adaption of the game was serialized in early issues of video game magazine GamePro.' FROM games WHERE igdb_id = 26599 ON CONFLICT (game_id, language_code) DO NOTHING;
