INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yuurei-kun', 141848, '1989-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mxd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8vx4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yuurei-kun', 'Mr. Ghost is a side, and vertical (the game alternates between the two), scrolling shoot-‘em-up where you play a buck-toothed ghost who’s being bullied by other ghosts, jumping spiders, and crows, probably about his prominent teeth. Mr. Ghost plays remarkably close to Irem’s Mr Heli, so much so that they could, in fact, be related. Both games let your character move in eight directions, both allow you to deform parts of the environment, and both have a super-deformed look to them. What sets this game aside, though, is its combat system. Mr Ghost dispatches a little sperm looking ghost at enemies and can only redeploy him after he’s returned. Mr Ghost can also perform a bum rush to destroy enemies sneaking up behind him or break bricks.' FROM games WHERE igdb_id = 141848 ON CONFLICT (game_id, language_code) DO NOTHING;
