INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakigake!! Otokojuku: Shippuu Ichi Gou Sei', 'Sakigake takes place at a school called Otokojuku, which is a private boy school that teaches Oendan to student delinquents. Oendan is basically a cheering squad that is somewhat similar to cheerleaders, except they focus mostly on noise and atmosphere than being acrobatic. The school is run by the principal Heihachi Edajima, who uses martial arts to train his students to be better people for society.' FROM games WHERE igdb_id = 48674 ON CONFLICT (game_id, language_code) DO NOTHING;
