INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ikari III: The Rescue', 'The presidential candidate''s daughter has been kidnapped! It is your job to get past enemy lines and rescue her. This is the third game in the Ikari Warriors series, and features similar arcade/action gameplay. The screen is a top down view which scrolls vertically, with numerous bad guys to defeat. You start the game with just your fists, and as the levels progress you can find weapons and other objects to help you out.' FROM games WHERE igdb_id = 48054 ON CONFLICT (game_id, language_code) DO NOTHING;
