INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GNU Go', 'GNU Go is a free software program by the Free Software Foundation that plays Go. Its source code is quite portable, and can be easily compiled for Linux, as well as other Unix-like systems, Microsoft Windows and macOS; ports exist for other platforms.' FROM games WHERE igdb_id = 194306 ON CONFLICT (game_id, language_code) DO NOTHING;
