INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Putt Putt Golf', 'Putt Putt Golf by Pack-In-Video is one of many golf games for the Famicom and the Famicom Disk System, but one of the few to take players through an abstract world rather than an approximation of a real golf course. The goal of each stage is to reach the hole on the green and pot the ball in as few strokes as possible, but each of the courses are covered with various obstacles - some animated, some stationary. The player must navigate around them (or use them to their advantage, in some cases) in order to achieve the best score.' FROM games WHERE igdb_id = 41311 ON CONFLICT (game_id, language_code) DO NOTHING;
