INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tir-nan-óg II: The Sign of Chaos', 'The Sign of Chaos is a sequel to Descendants of Danaan, set in the same fantasy world based on Irish mythology. The legendary hero has accomplished his mission, but the forces of darkness were too strong, and as a result four kingdoms were engulfed in chaos, overrun by monstrous creatures. The hero travels to the land of Fianapia and teams up with the local princess to cleanse the country of evil.
