INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'UFO', 'UFO is a flight simulator that utilizes 3D terrain modeling technology to create a unique spacecraft piloting experience. Players control a UFO with unconventional flight mechanics, including anti-gravity adjustment, pitch, roll, yaw, and multi-directional thrust capabilities. The objective involves searching for fuel while avoiding human detection using a translucer for radar invisibility. Advanced features include anti-laminar transducers to eliminate drag, gluon disruptor propulsion systems, and various equipment options such as landing pods, illuminator beams, probes, gravitons, shields, and teleportation. Players can dock with a mother ship to trade scavenged fuel for supplies and capture earthly aircraft using a tractor beam.' FROM games WHERE igdb_id = 100199 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 100199 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
