INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shooting-range', 48247, '1989-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ovd.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shooting Range', 'The aim is to shoot the discs on the screen so that you can acquire enough points to pass the clearing point score of that particular stage without your time or energy running out. You can choose between different difficulty levels. They affect the time you have to complete the stages. For difficulty level 1 you get 300 game time, difficulty level 2 gives you 250 and the 3rd difficulty level only 200. Items you can shoot during the game include an hourglass which extends time by 50, an E which gives you 100 points + 1 Energy bar, an E in a white square which gives you 100 points + 2 Energy bars, a Reverse E which gives you 1 Energy bar and C or W symbol which both give only 100 points each. Each disc you shoot above an enemy is worth between 100-500 points. The game contains three stages that involve a western, ghost house, and a space theme. There is also a bonus stage where you try to shoot as many bottles as possible. In the party game mode, you compete to have the highest score.' FROM games WHERE igdb_id = 48247 ON CONFLICT (game_id, language_code) DO NOTHING;
