INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Amazing Spider-Man and Captain America in Dr. Doom''s Revenge!', 'Latverian president Dr. Doom is a terrible enemy, so when he hatches a plan to blow up New York City with a stolen Atomic bomb, one Marvel superhero is not enough to stop him. As the lavishly-drawn comic bundled with the game explains, Spider-Man and Captain America must join forces to go to Latveria and foil his plans.
