INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gaudi: Barcelona no Kaze', 'Gaudi: Barcelona no Kaze was the first adventure developed by Wolf Team. It takes place in the Spanish city of Barcelona, which just the year before the release of the game was chosen for the celebration of the 25th Olympic Games. This is important to mention as the game takes place in the summer of 1992, the time at which the Olympic Games were being held in Barcelona.' FROM games WHERE igdb_id = 118312 ON CONFLICT (game_id, language_code) DO NOTHING;
