INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pete Rose Baseball', 'From the crack of the bat, make split-second decisions as you choose which fielder makes the play. Throw popular Major League pitches - fast balls, curves, change-ups, screwballs and sinkers. (Spitballs?) Head-to-head action with your friends or against the computer. Complete TV-like coverage, with six camera angles you''re always right there where the action is. Play to a packed stadium complete with cheering crowd and organist.' FROM games WHERE igdb_id = 117320 ON CONFLICT (game_id, language_code) DO NOTHING;
