INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ankoku Shinwa: Yamato Takeru Densetsu', 'The game is based on old Japanese legends about Yamato Takeru, a legendary hero of ancient Japan. The game starts when Yamato Takeru is a thirteen-year-old boy. His father was killed under mysterious circumstances. Searching his things, the boy found a postcard that gave him his first clue for the investigation. From that moment, his adventure begins.' FROM games WHERE igdb_id = 48633 ON CONFLICT (game_id, language_code) DO NOTHING;
