INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Montezuma''s Revenge Featuring Panama Joe', 'The player controls a on-screen character called Panama Joe, moving him from room to room in the labyrinthine underground of the 16th century Aztec temple of emperor Montezuma II, filled with enemies, obstacles, traps and dangers. The objective is to score points by gathering jewels along the way. Panama Joe must find keys to open doors, collect and use equipment such as torches, swords, amulets, etc. without losing his life. Obstacles are laser gates, conveyor belts, disappearing floors and fire pits.' FROM games WHERE igdb_id = 46138 ON CONFLICT (game_id, language_code) DO NOTHING;
