INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Champ', 'The Champ is a boxing video game published in 1989-1991 for the Amiga, Commodore 64 and ZX Spectrum computers by the Swiss company Linel, which was based in Liechtenstein at the time. The original for the Amiga is from Switzerland, while the conversions are the work of the British company Pantheon Software. The Amiga and Commodore 64 versions include Gonna Fly Now, a song from the famous boxing film Rocky, presumably used with a regular licence since composer Bill Conti is credited in the game manual.' FROM games WHERE igdb_id = 78689 ON CONFLICT (game_id, language_code) DO NOTHING;
