INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Face Off!', 'Face Off! is a hockey game where you can play an exhibition game, an entire season or go straight to the playoffs and lead your team to the Stanley Cup. For the basic hockey gameplay a traditional side view is used, but whenever you or your opponent shoots at the goal the game switches to the special Shot Cam view. Occasionally when someone commits a nasty foul the game turns into a one-on-one fighting game; he who wins the fight can stay on the ice while the loser must spend some time in the penalty box.' FROM games WHERE igdb_id = 50795 ON CONFLICT (game_id, language_code) DO NOTHING;
