INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Class Baseball', 'This game belongs in the Baseball Hall of Fame. Nothing takes you out to the ballgame like World Class Baseball! It tests all your baseball knowledge and skills. Bunt. Throw a slider. A change-u. Pick runners off base. Call in a relief pitcher. Hear the roar of the crowd and the crack of the bat. Play another player. Play against the computer. Play the Turbo Champs. Knock the dirt from your spikes. You''re up!' FROM games WHERE igdb_id = 37734 ON CONFLICT (game_id, language_code) DO NOTHING;
