INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brick Game', 'Tetris clone. This game comes in many different variations, ranging from normal Tetris pieces to complex variations featuring pentomino (five-block) pieces, random blocks appearing after time, falling "bombs" that can clear the blocks and even pieces that could shoot or pemetrate through other blocks. To avoid possible copyright infringement of the original Tetris, this game is simply named as the titular "Brick Game" or "Wooden Blocks" on the console''s packaging or user manual.' FROM games WHERE igdb_id = 288262 ON CONFLICT (game_id, language_code) DO NOTHING;
