INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rock''n'' Ball', 'Nostalgic pinball is back with some very modern concepts! Enjoy seven different games with six different characters such as Twister Tom for Pinball, Rock''n'' Roller Billy for Sports Pinball, and more! Team up with your favorite Rock''n'' Ball character and reach for higher and higher scores! Pinball is famous in video game history. Challenge your skills against Rock''n'' Ball''s brand new twists on this popular game!' FROM games WHERE igdb_id = 48206 ON CONFLICT (game_id, language_code) DO NOTHING;
