INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Volley Ball', 'Super Volley Ball is an indoor volleyball game for one or two players. The single player mode offers two game options: normal game and World League. Choosing normal game pits the player against the computer in a single game. Choosing World League pits the player against all other teams available. A password save is available in this mode.' FROM games WHERE igdb_id = 4440 ON CONFLICT (game_id, language_code) DO NOTHING;
