INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spark Man', 'You play a robot called Spark Man and the screen advances from left to right. Kill all the enemies with your standard weapon or weapons with limited shots available within the stages. You can also shoot the bad guys face-to-face with your leg. During each boss stage you have to kill a certain number of enemies to continue on to the next level. The game ends after Level 9' FROM games WHERE igdb_id = 40169 ON CONFLICT (game_id, language_code) DO NOTHING;
