INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Solvers: Midnight Rescue!', 'Morty Maxwell, the master of mischief, is up to his old tricks again, and this time the Shady Glen School is the target of his outlandish plot. Armed with paint that turns things invisible and five robot paintbrushes, he''s trying to erase the school, and you only have until midnight to stop him. To stop the evil mastermind, kids will need to read for clues and collect evidence to determine which of the robots is really the Master of Mischief in disguise.' FROM games WHERE igdb_id = 46646 ON CONFLICT (game_id, language_code) DO NOTHING;
