INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bouncing Bluster', 'Bouncing Bluster is a 1 - 2 player arcade game similar to Arkanoid. The player controls a paddle on the bottom of the screen that moves horizontally, and must bounce a ball to hit and destroy and bricks on the screen. The player starts with 5 lives, and it''s game over when all are lost. Various powerups fall from the screen as blocks are broken, including multiple balls, the ability to shoot lasers, sticky balls, and thinner/wider paddles.' FROM games WHERE igdb_id = 181435 ON CONFLICT (game_id, language_code) DO NOTHING;
