INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snake', 'In this well-known game, the player takes control of a worm (or snake) which is constantly moving forward, eating mushrooms. The player can use the arrow keys to turn the worm, but must take care not to run into the surrounding walls, the obstacles, or the worm itself. Once the worm has eaten 5 regular mushrooms, doors open in the walls, through which the player can advance to the next level.' FROM games WHERE igdb_id = 294214 ON CONFLICT (game_id, language_code) DO NOTHING;
