INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asuka & Asuka', 'A mysterious invasion force known as the Galaxy Highters invades the Earth in the year 1996. With their abilities in space time manipulation, they are able to invade several time lines in Earth’s history and occupy each one simultaneously. In order to stop the Galaxy Highters, Earth’s militaries design the ''Flying Bird'', a jet fighter capable of time travel, enabling it to fly into occupied time lines.' FROM games WHERE igdb_id = 38515 ON CONFLICT (game_id, language_code) DO NOTHING;
