INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Emmanuelle', 'Emmanuelle is an erotic graphical adventure game from Coktel Vision, originally released in 1989 for Amiga, Atari ST, and IBM PC (DOS). The game was developed by Muriel Tramis, who is perhaps better remembered from her games in the Gobliiins series. The game is considered to slightly erotic, but not pornographic' FROM games WHERE igdb_id = 37238 ON CONFLICT (game_id, language_code) DO NOTHING;
