INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ALF the Alien Life Form', 'ALF has an enormous appetite (eating everything he can get his hands on); he is also troublesome, sarcastic, slovenly and cynical, and sometimes he puts himself at the risk of being discovered while perpetrating some of his often-unintentional pranks. However, if things have gone too far, he does as much as possible to make up for his mistakes, generally with positive results.' FROM games WHERE igdb_id = 45669 ON CONFLICT (game_id, language_code) DO NOTHING;
