INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baron', 'Baron is an arcade-adventure game in which you play as a prince whose father''s friend, the wizard, has been kidnapped and imprisoned by the evil baron. The king has sent out an army, but you also wanted to help. Now you are in the castle of the baron and have to find 4 items which you bring to the cell of the wizard.' FROM games WHERE igdb_id = 128441 ON CONFLICT (game_id, language_code) DO NOTHING;
