INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The World of Animals', 'While making his morning rounds, the Farmer finds an egg shell. He wonders what kind of animal could have come from the shell. You actually get involved helping the Farmer, the Bee, Mother Goose and Saymour and his friends sift through a series of clues to solve the mystery and meet all kinds of farm and wild animals on the way! And, you''ll even get personal phone calls from Saymour and the gang!' FROM games WHERE igdb_id = 293980 ON CONFLICT (game_id, language_code) DO NOTHING;
