INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trouble in Mother Goose Land', 'Get ready for the grand opening of the wonderful Mother Goose Land amusement park. Mother Goose, Saymour, and their friends need your help with the preparations for the big event! You''ll be meeting your favorite nursery rhyme characters and learning the rhymes that made them famous. But, while everyone''s busy with the preparing, someone is out to spoil the fun! And, he has to be found out so the work can get done! So come along and actually get involved in making the arrangements - and solve the mystery of who''s making the mischief - and why! And, you''ll even get personal phone calls from Saymour and the gang!' FROM games WHERE igdb_id = 293983 ON CONFLICT (game_id, language_code) DO NOTHING;
