INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aleste Gaiden', 'Aleste Gaiden is a vertical shoot ''em up video game developed by Compile in 1989. It was released onto MSX2 in Japan only. It was originally released as part of the Disc Station Special Vol. 4. As it''s title implies, it is a spin-off which retells the story of the first game in a different setting.' FROM games WHERE igdb_id = 47517 ON CONFLICT (game_id, language_code) DO NOTHING;
