INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crime City', 'Play as policemen Tony Gibson and/or Raymond Broady in this multi-scrolling beat-em-up shooter. Shoot at a variety of enemies as you make your way through the various levels to reach the end bosses. Pick up power-ups including better weaponry, bullets and health drinks.' FROM games WHERE igdb_id = 6784 ON CONFLICT (game_id, language_code) DO NOTHING;
