INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Halloween Night II', 'Halloween Night II is a 1989-1991 children''s game by BugByte Inc. for Macintosh. On Halloween night, monsters knock at your door looking for candy. You hand them candy, cheer them up, and wait for the next monster to come by. While you''re waiting, you can pet your cat or look out the window.' FROM games WHERE igdb_id = 209448 ON CONFLICT (game_id, language_code) DO NOTHING;
