INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pachinko Time', 'Pachinko Time sees you participating in the Japanese past time of pachinko, where you launch numerous balls onto a board, pinball-style, aiming at specific receptacles to extend game play. It offers offers 100 different virtual tables to play at, each requiring you whittle down a specific target score to zero before you run out of balls. Each area on the world map features a number of different tables; completing three will allow access to new areas with more tables.' FROM games WHERE igdb_id = 131141 ON CONFLICT (game_id, language_code) DO NOTHING;
