INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hydefos', 'Hydefos is a shoot ''em up with smooth scrolling, a rarity on the MSX, where the scrolling is usually choppy, and a feat developer Hertz had already accomplished on a previous title, action platformer Psychic World. You pilot one of five ships through levels featuring branching paths, so two play-throughs could be different depending on where you go.' FROM games WHERE igdb_id = 292848 ON CONFLICT (game_id, language_code) DO NOTHING;
