INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('off-the-wall', 12894, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wy8symtmxnub2qdf7gtx.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Off the Wall', 'One or two players bust through blocks in various formations using a paddle and ball, trying to reach an exit located in the center of the blocks in order to advance to the next wave. There are glowing blocks which give you "Power Ups" Xextra ball, Ccatch ball, I invinciball, S slow ball, B bigger paddle, F firepower which allows you to shoot blocks with a gun located in the center of your paddle. You get points for busting blocks, but get more bonus points for blocks left when you reach the exit.' FROM games WHERE igdb_id = 12894 ON CONFLICT (game_id, language_code) DO NOTHING;
