INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Theldrow', 'Theldrow is a turn-based computer role-playing game, written in 1989 by Glenn Andreas. The game featured a turn-based first person perspective interface similar to early Might and Magic games, pixel art (originally black-and-white), and a very original fantasy setting. It is a very difficult game.' FROM games WHERE igdb_id = 171249 ON CONFLICT (game_id, language_code) DO NOTHING;
