INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Ace', 'Taking a fair amount of inspiration from Sega''s After Burner II, Battle Ace is a sci-fi based cockpit shooter. Gameplay is purely arcade style, with a standard machine gun and lock-on missiles to take down the enemy aggressors. There''s little more to it than that.' FROM games WHERE igdb_id = 38103 ON CONFLICT (game_id, language_code) DO NOTHING;
