INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Autobots', 'Clear levels by making robots smash into one another. You do this by manipulating them to crash into one another using your player icon (the robots always move towards your player, so if you can get two robots moving on the same lateral plane towards you then they are an easy kill.) When two robots crash into one another they form a pile of debris which can also be used to destroy robots.' FROM games WHERE igdb_id = 14457 ON CONFLICT (game_id, language_code) DO NOTHING;
