INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Sawyer no Bouken', 'The original Japanese version of The Adventures of Tom Sawyer. The level order is changed in the English version (perhaps so as not to confuse players by starting with the rafting stage). The Japanese original''s level 5, the pirate ship, is the English version''s level 1, both making the beginning of the game much more difficult, and making the plot non-coehesive.' FROM games WHERE igdb_id = 280978 ON CONFLICT (game_id, language_code) DO NOTHING;
