INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('walter-payton-football', 45629, '1989-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co48oe.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Walter Payton Football', 'It''s the snap! You sweep to the right. the quarterback hands you the ball. You head for daylight as the linemen open a hole. Suddenly, 250 lbs. of screaming tackle is heading your way. He wants to make you splat city. What will you do? This game gives you the chance to find out. With Walter Payton Football you can play against the computer, or against a friend, in a Monday Night Game or in a series on the Road to the Superbowl. Choose from 28 west, central and eastern teams. Offense and defense. Should you run or pass? Will a reverse throw ''em off guard? In the middle of a hot series, you can save your standings with a Password save. The Superbowl ring has never been this close. If you like football, then Sega''s Walter Payton Football is the game for you!' FROM games WHERE igdb_id = 45629 ON CONFLICT (game_id, language_code) DO NOTHING;
