INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wheel of Fortune: New 3rd Edition', 'Providing new puzzle phrases, the third edition of the Wheel of Fortune series of games based on the popular television show, brings the same fun as the original. Up to three contestants can play. Players compete to solve the puzzle by spinning a wheel and guessing hidden letters of a person, place, thing, phrase or other category.' FROM games WHERE igdb_id = 47182 ON CONFLICT (game_id, language_code) DO NOTHING;
