INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyberbig', 'A terrible danger stalks the life of the planet Gerion XXIII, of which this base is a satellite, already practically devoid of animal life. Only one monstrous species remains, the Cyberbig, beings whose voracity has no limits, they devour everything in their path, even metal. The alternative was clear: destroy or be destroyed.' FROM games WHERE igdb_id = 13539 ON CONFLICT (game_id, language_code) DO NOTHING;
