INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Faria: A World of Mystery and Danger!', 'The player controls a female character throughout most of the game. A male character is played towards the end of the game. The game uses "Levels", HP, items, and upgrades. Three game saving slots are used, rather than passwords. Overhead view action oriented battles. Randomly generated battles while traversing the overworld.' FROM games WHERE igdb_id = 48060 ON CONFLICT (game_id, language_code) DO NOTHING;
