INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Flight Simulator 4.0', 'Like the previous release, version 4 included scenery for five cities (New York, Seattle, San Francisco, Los Angeles, and Chicago). It featured CGA through VGA (in EGA resolution) support, and multi-user play. Version 4 also supported newer add-ons such as Microsoft''s Aircraft & Scenery Designer, and Sublogic''s USA scenery series.' FROM games WHERE igdb_id = 3356 ON CONFLICT (game_id, language_code) DO NOTHING;
