INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Belial', 'Belial is 2D side-scrolling platform game, clone of Ghosts ''N Goblins, without story in-game. The player controls a bearded man, who can shoot small bullets. He goes into the right side of the screen, shoots various enemies (like zombies, bouncing Jack-o''-lanterns, jumping one-eyed monsters, plants etc.), and jumps over obstacles and holes. The game hasn''t restarted points - when players lost life, he returns to starting point on each level.' FROM games WHERE igdb_id = 14295 ON CONFLICT (game_id, language_code) DO NOTHING;
