INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tecmo-knight', 40002, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qb9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwk7w.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tecmo Knight', 'The protagonist Tecmo Knight has the assistance of "Smokeman" and "Tiger". Pressing the "change" button allows Tecmo Knight to switch between the two. Smokeman uses powerful punches and kicks against enemies while Tecmo Knight rides him. While riding the tiger, Tecmo Knight has the use of a spiked ball and chain less powerful than Smokeman''s attacks, but with greater range. When collecting the special dragon skull that randomly appears after defeating an enemy, the Tecmo Knight will summon the most powerful creature to ride on in the game: the Flying Dragon. Tecmo Knight is immune to attack while riding Flying Dragon, whose breath kills any monster in the game instantly, including the stage-end bosses. Using the "jump and attack" maneuver, Tecmo Knight can bound Smokeman or the tiger onto enemies and pummel them.
