INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Their Finest Hour: The Battle of Britain', 'Their Finest Hour: The Battle of Britain is a World War II combat flight simulation game by Lawrence Holland, released in October 1989 for the Amiga, Atari ST and MS-DOS systems. It was the second game in the trilogy of World War II titles by Lucasfilm Games, the others being Battlehawks 1942 (1988) and Secret Weapons of the Luftwaffe (1991). The game was released with a 192-page manual written by Victor Cross, that provided a detailed historical overview of the battle and pilots'' perspectives. An expansion pack, Their Finest Missions: Volume One, was released in 1989.' FROM games WHERE igdb_id = 208 ON CONFLICT (game_id, language_code) DO NOTHING;
