INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angel Hearts', 'Angel Hearts is a dead simple RPG developed by ELF in 1989. The gameplay resembles that of "dungeon crawlers", meaning that there are no friendly areas; though the view for exploration is top-down rather than first-person (which is reserved for the turn-based battles). The gameplay mechanics are mostly confined to fighting random enemies and earning enough experience points to go up a level and standing a chance against the next "boss" enemy. There is no equipment system, and battle commands are restricted to "Attack", "Escape", and "Item".' FROM games WHERE igdb_id = 67342 ON CONFLICT (game_id, language_code) DO NOTHING;
