INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Breaker', 'This futuristic shooter combines two distinct styles of gameplay into a multi-level romp through space. The colony planets of New Chicago have been overrun by gangs of Rrampon invaders, and a state-of-the-art space cruiser has been sent in to purge the infestation. It''s up to the Star Breaker, and its android pilot, to destroy the enemy''s airborne forces and dispatch the interlopers underground.' FROM games WHERE igdb_id = 13082 ON CONFLICT (game_id, language_code) DO NOTHING;
