INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digital Champ', 'Take to the ring and fight against strangely familiar looking opponents in this first-person boxing game. Block and dodge with the D-Pad while using the buttons to punch with either left or right fists. Hold the button down and you get a more powerful hit, but it requires more timing and accuracy to be effective.' FROM games WHERE igdb_id = 42076 ON CONFLICT (game_id, language_code) DO NOTHING;
