INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lords of the Rising Sun', 'The Battle Lines are Drawn! Welcome to the twelfth century Japan! Your bitter rivals, the Taira clan, have murdered your father and subverted the emperor. In an epic quest to become SHOGUN, and thus redeem the family honor, you’ll command vast armies of samurai warriors; defend yourself against ninja assassins; lay siege against mighty fortresses; negotiate alliances; and confront your enemies in personal combat!' FROM games WHERE igdb_id = 8669 ON CONFLICT (game_id, language_code) DO NOTHING;
