INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaizou Choujin Schbibinman', 'A crazy, yet genius professor named "Doc" sends two of his brand new and most skilled cyborgs against an army of evil machines that have taken over the city. With the help of their special suits and powerful energy-swords, they fight waves of enemies of increasing strength, as well as bigger and badder bosses until they eventually reach the lair of their furious leader - the evil Dark Skull.' FROM games WHERE igdb_id = 42052 ON CONFLICT (game_id, language_code) DO NOTHING;
