INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aldo Again', 'Aldo Again is a single player clone of Donkey Kong. The objective of the game is to take Aldo to the treasure chest, avoiding falling barrels along the way. When the chest is reached any remaining time is added to the player''s score. Time is an important resource and playing time can be extended by picking up prizes en-route. The game is entirely keyboard controlled.' FROM games WHERE igdb_id = 50087 ON CONFLICT (game_id, language_code) DO NOTHING;
